const photos=Array.from(document.querySelectorAll('[data-gallery-photo]')),viewer=document.querySelector('#photo-viewer'),image=document.querySelector('#viewer-image'),caption=document.querySelector('#viewer-caption'),photoCount=document.querySelector('#viewer-count');let photoIndex=0,photoTrigger=null;
function showPhoto(index){photoIndex=(index+photos.length)%photos.length;const photo=photos[photoIndex];image.src=photo.getAttribute('href');image.alt=photo.querySelector('img').alt;caption.textContent=image.alt;photoCount.textContent=`Foto ${photoIndex+1} daripada ${photos.length}`;document.querySelector('.viewer-controls').hidden=photos.length<2;viewer.setAttribute('aria-label',`Foto ${photoIndex+1}: ${image.alt}`)}
photos.forEach((photo,index)=>photo.addEventListener('click',event=>{if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();photoTrigger=photo;showPhoto(index);viewer.showModal();document.body.classList.add('photo-viewer-open');document.querySelector('#viewer-close').focus()}));
function closeViewer(){document.body.classList.remove('photo-viewer-open');viewer.close()}
viewer.addEventListener('cancel',()=>document.body.classList.remove('photo-viewer-open'));
document.querySelector('#viewer-close').addEventListener('click',closeViewer);document.querySelector('#viewer-prev').addEventListener('click',()=>showPhoto(photoIndex-1));document.querySelector('#viewer-next').addEventListener('click',()=>showPhoto(photoIndex+1));viewer.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();showPhoto(photoIndex+1)}if(event.key==='ArrowLeft'){event.preventDefault();showPhoto(photoIndex-1)}});viewer.addEventListener('click',event=>{if(event.target===viewer){const rect=viewer.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeViewer()}});viewer.addEventListener('close',()=>{document.body.classList.remove('photo-viewer-open');photoTrigger?.focus({preventScroll:true})});
